"use client";

import { useCallback, useEffect, useState } from "react";

export default function ProjectGallery({
  images,
  title,
}: {
  images: readonly string[];
  title: string;
}) {
  const [active, setActive] = useState<number | null>(null);

  const close = useCallback(() => setActive(null), []);
  const previous = useCallback(() => {
    setActive((current) =>
      current === null ? null : (current - 1 + images.length) % images.length
    );
  }, [images.length]);
  const next = useCallback(() => {
    setActive((current) =>
      current === null ? null : (current + 1) % images.length
    );
  }, [images.length]);

  useEffect(() => {
    if (active === null) return;
    const onKey = (event: KeyboardEvent) => {
      if (event.key === "Escape") close();
      if (event.key === "ArrowLeft") previous();
      if (event.key === "ArrowRight") next();
    };
    document.body.style.overflow = "hidden";
    window.addEventListener("keydown", onKey);
    return () => {
      document.body.style.overflow = "";
      window.removeEventListener("keydown", onKey);
    };
  }, [active, close, previous, next]);

  return (
    <>
      <div className="gallery">
        {images.map((src, index) => (
          <button
            type="button"
            className="galleryBtn"
            key={`${src}-${index}`}
            onClick={() => setActive(index)}
            aria-label={`Abrir ${title}, imagem ${index + 1}`}
          >
            <img src={src} alt={`${title} — imagem ${index + 1}`} />
            <span>Ver imagem</span>
          </button>
        ))}
      </div>

      {active !== null && (
        <div className="projectLightbox" role="dialog" aria-modal="true">
          <button type="button" className="lbBackdrop" onClick={close} aria-label="Fechar galeria" />
          <button type="button" className="lbClose" onClick={close} aria-label="Fechar">×</button>

          {images.length > 1 && (
            <button type="button" className="lbPrev" onClick={previous} aria-label="Imagem anterior">‹</button>
          )}

          <figure className="lbFigure">
            <img src={images[active]} alt={`${title} — imagem ${active + 1}`} />
            <figcaption>{active + 1} / {images.length}</figcaption>
          </figure>

          {images.length > 1 && (
            <button type="button" className="lbNext" onClick={next} aria-label="Imagem seguinte">›</button>
          )}
        </div>
      )}
    </>
  );
}
